CREATE VIEW momentum_events_canonical AS SELECT me.ticker, COALESCE(me.date, me.event_date) AS event_date_canonical, me.momentum_pct, CASE  WHEN ((me.date IS NOT NULL)) THEN ('file1') WHEN ((me.event_date IS NOT NULL)) THEN ('file2') ELSE NULL END AS source_file, ic."class" AS instrument_class, ic.vendor_type AS vendor_type, ((me.prev_close < 0.01) OR (me.momentum_pct >= 10000)) AS flag_bad_denominator, ef.flag_trades_mom_outlier AS flag_trades_mom_outlier, COALESCE(ef.flag_missing_event_day, CAST('f' AS BOOLEAN)) AS flag_missing_event_day, COALESCE(ef.flag_window_calendar_bug, CAST('f' AS BOOLEAN)) AS flag_window_calendar_bug, COALESCE(ef.repaired_1c, CAST('f' AS BOOLEAN)) AS repaired_1c, EXISTS(SELECT 1 FROM read_parquet('E:/Trading Research/results/phase_0c/artifacts/folder_inventory.parquet') AS fi WHERE ((fi.ticker = me.ticker) AND (fi.date_is_none = CAST('f' AS BOOLEAN)) AND (fi.date = CAST(COALESCE(me.date, me.event_date) AS VARCHAR)) AND (round(TRY_CAST(fi.momentum_str AS DOUBLE), 2) = round(me.momentum_pct, 2)))) AS has_folder, (ft_distinct.ticker IS NOT NULL) AS trades_ingested, (fq_distinct.ticker IS NOT NULL) AS quotes_ingested, ((ic."class" IN ('common', 'common_adr')) AND (NOT COALESCE(flag_bad_denominator, CAST('f' AS BOOLEAN))) AND (NOT COALESCE(ef.flag_trades_mom_outlier, CAST('f' AS BOOLEAN))) AND (NOT COALESCE(ef.flag_missing_event_day, CAST('f' AS BOOLEAN)))) AS in_scope, cc.coverage_class AS coverage_class, cc.quotes_full_window AS quotes_full_window FROM momentum_events AS me LEFT JOIN read_parquet('E:/Trading Research/results/phase_1b/artifacts/instrument_classification.parquet') AS ic ON ((me.ticker = ic.ticker)) LEFT JOIN (SELECT DISTINCT ticker, event_date, round(momentum_pct, 2) AS mom_2dp FROM filtered_trades) AS ft_distinct ON (((me.ticker = ft_distinct.ticker) AND (COALESCE(me.date, me.event_date) = ft_distinct.event_date) AND (round(me.momentum_pct, 2) = ft_distinct.mom_2dp))) LEFT JOIN (SELECT DISTINCT ticker, event_date, round(momentum_pct, 2) AS mom_2dp FROM filtered_quotes) AS fq_distinct ON (((me.ticker = fq_distinct.ticker) AND (COALESCE(me.date, me.event_date) = fq_distinct.event_date) AND (round(me.momentum_pct, 2) = fq_distinct.mom_2dp))) LEFT JOIN read_parquet('E:/Trading Research/results/phase_2/artifacts/coverage_class.parquet') AS cc ON (((me.ticker = cc.ticker) AND (COALESCE(me.date, me.event_date) = cc.event_date_canonical) AND (round(me.momentum_pct, 2) = round(cc.momentum_pct, 2)))) LEFT JOIN read_parquet('E:/Trading Research/results/phase_1b/artifacts/event_flags.parquet') AS ef ON (((me.ticker = ef.ticker) AND (COALESCE(me.date, me.event_date) = ef.event_date_canonical) AND (round(me.momentum_pct, 2) = round(ef.momentum_pct, 2))));
